251	function DailyBars({ days }) {
252	  const W = 760;
253	  const H = 180;
254	  const max = Math.max(1, ...days.map((d) => d.passed + d.failed + d.running));
255	  const slot = W / days.length;
256	  const bar = slot * 0.56;
257	  return (
258	    <svg className="daily" viewBox={`0 0 ${W} ${H + 26}`} role="img" aria-label="Mods per day by outcome">
259	      {[0.25, 0.5, 0.75, 1].map((f) => (
260	        <line key={f} x1="0" x2={W} y1={H - H * f} y2={H - H * f} className="grid" />
261	      ))}
262	      {days.map((d, i) => {
263	        const x = i * slot + (slot - bar) / 2;
264	        let y = H;
265	        return (
266	          <g key={d.key}>
267	            {[
268	              ["passed", d.passed],
269	              ["failed", d.failed],
270	              ["running", d.running],
271	            ].map(([kind, n]) => {
272	              if (!n) return null;
273	              const h = (n / max) * H;
274	              y -= h;
275	              return <rect key={kind} className={kind} x={x} y={y} width={bar} height={h} rx="3" />;
276	            })}
277	            {(i % 2 === 0 || i === days.length - 1) && (
278	              <text x={x + bar / 2} y={H + 18} textAnchor="middle">
279	                {d.key.slice(5).replace("-", "/")}
280	              </text>
281	            )}
282	          </g>
283	        );
284	      })}
285	    </svg>
286	  );
287	}
