import React from "react";
import { call } from "../../api.js";

export const PHASES = [
  ["spec", "Spec"],
  ["repo", "Repo"],
  ["build", "Build"],
  ["compile", "Compile"],
  ["deploy", "Deploy"],
  ["playtest", "Playtest"],
  ["fix", "Fix"],
  ["done", "Done"],
];

export const ROLE = {
  spec: "Spec agent",
  builder: "Builder",
  fixer: "Fixer",
  playtester: "Playtester",
  benana: "Benana",
  seeded: "Seeded fixture",
};

const STATUS = {
  queued: "Queued",
  running: "Running",
  passed: "Passed",
  failed: "Failed",
  stopped: "Stopped",
  pass: "Pass",
  fail: "Fail",
  blocked: "Blocked",
  pending: "Not run",
};

export function phaseIndex(mod) {
  if (!mod) return -1;
  if (mod.phase === "fix") return 6;
  return PHASES.findIndex(([key]) => key === mod.phase);
}

export function latestVerdict(mod) {
  return [...(mod?.attempts || [])].reverse().find((a) => a.verdict)?.verdict || null;
}

export function allSessions(mods) {
  return mods
    .flatMap((mod) => [
      ...mod.sessions.map((s, i) => ({ ...s, mod, attemptN: null, key: `${mod.id}:spec:${i}` })),
      ...mod.attempts.flatMap((a) =>
        a.sessions.map((s, i) => ({ ...s, mod, attemptN: a.n, key: `${mod.id}:${a.n}:${i}` })),
      ),
    ])
    .sort((a, b) => (b.startedAt || 0) - (a.startedAt || 0));
}

export const sessionMs = (s) => (s.endedAt && s.startedAt ? s.endedAt - s.startedAt : null);

export const modSpend = (mod) => allSessions([mod]).reduce((n, s) => n + (s.usage?.costUsd || 0), 0);

export function fmtDuration(ms) {
  if (ms == null || ms < 0) return "";
  const s = Math.round(ms / 1000);
  return s < 60 ? `${s}s` : `${Math.floor(s / 60)}m ${s % 60}s`;
}

export const fmtMoney = (n) => `$${(n || 0).toFixed(2)}`;

export const shortSha = (sha) => (sha ? sha.slice(0, 7) : "");

export const shortModel = (m) => (m || "").replace(/^claude-/, "");

export function Status({ status, children }) {
  return (
    <span className={`status ${status}`}>
      <i />
      {children || STATUS[status] || status}
    </span>
  );
}

export function Icon({ name, size = 16 }) {
  const paths = {
    check: <path d="M4 8.5 6.8 11 12 5.5" />,
    x: <path d="M5 5l6 6M11 5l-6 6" />,
    alert: <path d="M8 4.5v4M8 11h.01" />,
    plus: <path d="M8 3.5v9M3.5 8h9" />,
    stop: <rect x="5" y="5" width="6" height="6" rx="1" />,
    folder: <path d="M2.5 4.5h4l1.5 1.5h5.5v6.5h-11z" />,
    code: <path d="M6 5 3 8l3 3M10 5l3 3-3 3" />,
    arrow: <path d="M4 8h8M8.5 4.5 12 8l-3.5 3.5" />,
  };
  return (
    <svg className="icon" width={size} height={size} viewBox="0 0 16 16" aria-hidden="true">
      {paths[name]}
    </svg>
  );
}

export function CheckIcon({ status }) {
  const s = status || "pending";
  const name = { pass: "check", fail: "x", blocked: "alert" }[s];
  return <span className={`check-icon ${s}`}>{name && <Icon name={name} size={12} />}</span>;
}

export function Empty({ children }) {
  return <p className="empty">{children}</p>;
}

export function PageHead({ title, sub, children }) {
  return (
    <header className="page-head">
      <div>
        <h1>{title}</h1>
        {sub && <p>{sub}</p>}
      </div>
      {children && <div className="page-actions">{children}</div>}
    </header>
  );
}

export function SectionHead({ title, count, children }) {
  return (
    <div className="section-head">
      <h3>
        {title}
        {count != null && <span className="count">{count}</span>}
      </h3>
      {children}
    </div>
  );
}

export function PlanChecks({ mod }) {
  const verdict = latestVerdict(mod);
  const byId = new Map((verdict?.checks || []).map((c) => [c.id, c]));
  const live = verdict?.live && mod.running;
  const checks = mod.testPlan?.checks || [];
  const passed = checks.filter((c) => byId.get(c.id)?.status === "pass").length;
  return (
    <section className="block">
      <SectionHead title="Test plan">
        {live ? <Status status="running">Live</Status> : checks.length > 0 && <span className="meta">{passed}/{checks.length} passing</span>}
      </SectionHead>
      {!mod.testPlan && <Empty>The spec agent is writing the test plan.</Empty>}
      <ul className="check-list">
        {checks.map((c) => {
          const r = byId.get(c.id);
          return (
            <li key={c.id} className={r?.status || "pending"}>
              <CheckIcon status={r?.status} />
              <div>
                <strong>{c.title}</strong>
                <p>{r?.observed || c.expect}</p>
              </div>
            </li>
          );
        })}
      </ul>
      {verdict?.serverErrors?.length > 0 && (
        <div className="alert">
          {verdict.serverErrors.length} server error{verdict.serverErrors.length === 1 ? "" : "s"}:{" "}
          {verdict.serverErrors[0].message.slice(0, 160)}
        </div>
      )}
    </section>
  );
}

export function TraceButton({ sessionId }) {
  const [trace, setTrace] = React.useState(null);
  if (!sessionId) return null;
  const label = trace
    ? trace.matched
      ? `${trace.traces.length} trace${trace.traces.length === 1 ? "" : "s"}`
      : trace.configured === false
        ? "Not configured"
        : "No trace yet"
    : "Trace";
  return (
    <button
      className="partner-link neatlogs"
      title="Look up this session in Neatlogs"
      onClick={() =>
        call("studio:evidence", { sessionId })
          .then(setTrace)
          .catch((e) => setTrace({ error: e.message, traces: [] }))
      }
    >
      <i />
      {label}
    </button>
  );
}

export function AttemptTimeline({ mod, onSelect }) {
  if (!mod.attempts.length) return <Empty>No attempts yet.</Empty>;
  return (
    <ol className="attempts">
      {mod.attempts.map((a) => (
        <li key={a.n} className={`attempt ${a.status}`}>
          <div className="attempt-head">
            <CheckIcon status={{ passed: "pass", failed: "fail", running: "running" }[a.status] || "pending"} />
            <strong>Attempt {a.n}</strong>
            <span className="meta">{a.role === "seeded" ? "Seeded fixture" : ROLE[a.role]}</span>
            <Status status={a.status} />
          </div>
          <div className="attempt-body">
            {a.failure && <p className="attempt-text">{a.failure.summary}</p>}
            {a.lesson && (
              <div className="lesson">
                <span>Lesson</span>
                <p>{a.lesson}</p>
              </div>
            )}
            {a.context && (
              <p className="meta">
                Read {a.context.entireCheckpoints} Entire checkpoint{a.context.entireCheckpoints === 1 ? "" : "s"}
                {a.context.neatlogsTrace ? " and a Neatlogs trace" : ""} before fixing
              </p>
            )}
            {(a.commit?.sha || a.commit?.checkpoint) && (
              <div className="attempt-refs">
                {a.commit?.sha && (
                  <button className="sha" onClick={() => onSelect?.(a)} disabled={!onSelect} title="View this commit">
                    {shortSha(a.commit.sha)}
                  </button>
                )}
                {a.commit?.checkpoint && (
                  <span className="partner-link entire static">
                    <i />
                    Checkpoint {a.commit.checkpoint.slice(0, 8)}
                  </span>
                )}
              </div>
            )}
            {a.sessions.length > 0 && (
              <ul className="sessions">
                {a.sessions.map((s, i) => (
                  <li key={i}>
                    <span className="session-role">{ROLE[s.role] || s.role}</span>
                    <span className="meta">
                      {[shortModel(s.model), fmtDuration(sessionMs(s)), s.usage?.costUsd ? fmtMoney(s.usage.costUsd) : ""]
                        .filter(Boolean)
                        .join(" · ")}
                    </span>
                    <TraceButton sessionId={s.sessionId} />
                  </li>
                ))}
              </ul>
            )}
          </div>
        </li>
      ))}
    </ol>
  );
}

export function PartnerStatus({ mod }) {
  const [cps, setCps] = React.useState(null);
  const p = mod.partners;
  React.useEffect(() => {
    if (!mod.repoDir) return;
    call("studio:checkpoints", { id: mod.id }).then(setCps).catch(() => {});
  }, [mod.id, mod.repoDir, mod.attempts.length, mod.status]);
  return (
    <ul className="partners">
      <li>
        <span className={`partner-dot entire ${p?.entire?.enabled ? "" : "off"}`} />
        <strong>Entire</strong>
        <span className="meta">
          {p?.entire?.enabled
            ? `${cps?.items?.length ?? "…"} checkpoints`
            : p?.entire?.error || "Not set up"}
        </span>
      </li>
      <li>
        <span className={`partner-dot neatlogs ${p?.neatlogs?.enabled ? "" : "off"}`} />
        <strong>Neatlogs</strong>
        <span className="meta">{p?.neatlogs?.enabled ? "Sessions traced" : p?.neatlogs?.error || "Not set up"}</span>
      </li>
    </ul>
  );
}

import React from "react";
import { call, on, ago } from "../../api.js";
import BuildPage from "./BuildPage.jsx";
import ModsPage from "./ModsPage.jsx";
import InsightsPage from "./InsightsPage.jsx";
import NeatlogsPage from "./NeatlogsPage.jsx";
import EntirePage from "./EntirePage.jsx";
import { Icon } from "./shared.jsx";
import "./studio.css";

const PAGES = [
  ["build", "Build"],
  ["mods", "Mods"],
  ["insights", "Insights"],
  ["neatlogs", "Neatlogs"],
  ["entire", "Entire"],
];

const ICONS = {
  build: <path d="M10 2.5 3.5 6v8L10 17.5l6.5-3.5V6L10 2.5zM3.5 6 10 9.5 16.5 6M10 9.5v8" />,
  mods: (
    <>
      <rect x="3" y="3" width="5.5" height="5.5" rx="1.2" />
      <rect x="11.5" y="3" width="5.5" height="5.5" rx="1.2" />
      <rect x="3" y="11.5" width="5.5" height="5.5" rx="1.2" />
      <rect x="11.5" y="11.5" width="5.5" height="5.5" rx="1.2" />
    </>
  ),
  insights: <path d="M3 16.5h14M6 13V9.5M10 13V5M14 13V8" />,
  neatlogs: (
    <>
      <circle cx="5" cy="5" r="1.8" />
      <circle cx="15" cy="5" r="1.8" />
      <circle cx="10" cy="15" r="1.8" />
      <path d="M6.5 6.3 9 13.4M13.5 6.3 11 13.4M6.8 5h6.4" />
    </>
  ),
  entire: <path d="M10 2.5 3 6.5l7 4 7-4-7-4zM3 10.5l7 4 7-4M3 14l7 4 7-4" />,
  workspace: <path d="M3.5 5h13M3.5 10h9M3.5 15h6" />,
};

export default function ModStudio({ onOpenWorkspace }) {
  const [page, setPage] = React.useState("build");
  const [mods, setMods] = React.useState([]);
  const [selectedId, setSelectedId] = React.useState(null);
  const [composing, setComposing] = React.useState(true);
  const [lessons, setLessons] = React.useState([]);
  const [game, setGame] = React.useState(null);
  const [error, setError] = React.useState("");
  const mod = mods.find((m) => m.id === selectedId) || null;
  const running = mods.find((m) => m.running) || null;

  const watchMod = (id) => {
    setSelectedId(id);
    setComposing(false);
    setPage("build");
  };
  const openMod = (id) => {
    setSelectedId(id);
    setPage("mods");
  };
  const newMod = () => {
    setComposing(true);
    setPage("build");
  };

  React.useEffect(() => {
    call("studio:list")
      .then((list) => {
        setMods(list);
        const live = list.find((m) => m.running);
        setSelectedId((id) => id || live?.id || list[0]?.id || null);
        if (live) setComposing(false);
      })
      .catch((e) => setError(e.message));
    call("studio:lessons").then(setLessons).catch(() => {});
    call("game:status").then(setGame).catch(() => {});
    const offs = [
      on("studio:mod", (next) => {
        setMods((prev) => [next, ...prev.filter((m) => m.id !== next.id)].sort((a, b) => b.createdAt - a.createdAt));
        if (next.status === "passed") call("studio:lessons").then(setLessons).catch(() => {});
      }),
      on("game:status", setGame),
    ];
    return () => offs.forEach((off) => off());
  }, []);

  const server = game?.server || "stopped";
  const bot = game?.bot === "online" ? "online" : "offline";

  return (
    <div className="studio">
      <nav className="sidebar" aria-label="Mod Studio">
        <div className="brand">
          <span className="brand-mark">B</span>
          <span>
            <strong>Benana</strong>
            <small>Mod Studio</small>
          </span>
        </div>

        <button className="new-mod" onClick={newMod}>
          <Icon name="plus" size={14} />
          New mod
        </button>

        <div className="nav">
          {PAGES.map(([key, label]) => (
            <button
              key={key}
              className={`nav-item ${page === key ? "active" : ""}`}
              onClick={() => setPage(key)}
              aria-current={page === key ? "page" : undefined}
            >
              <svg viewBox="0 0 20 20" aria-hidden="true">{ICONS[key]}</svg>
              {label}
              {key === "build" && running && <span className="live-dot" title="A mod is building" />}
            </button>
          ))}
        </div>

        <div className="side-section">
          <span className="side-label">Recent</span>
          <div className="recent">
            {mods.slice(0, 8).map((m) => (
              <button
                key={m.id}
                className={`recent-item ${page === "build" && !composing && m.id === selectedId ? "active" : ""}`}
                onClick={() => watchMod(m.id)}
                title={m.prompt}
              >
                <span className={`dot ${m.running ? "running" : m.status}`} />
                <span className="recent-name">{m.name}</span>
                <small>{ago(m.createdAt)}</small>
              </button>
            ))}
            {!mods.length && <p className="side-empty">Mods you build appear here.</p>}
          </div>
        </div>

        <div className="side-foot">
          <div className="runtime">
            <div>
              <span className={`dot ${server === "running" ? "passed" : server === "starting" ? "running" : "idle"}`} />
              Paper {game?.version || "server"}
              <small>{server === "running" ? "Running" : server === "starting" ? "Starting" : "Stopped"}</small>
            </div>
            <div>
              <span className={`dot ${bot === "online" ? "passed" : "idle"}`} />
              Test bot
              <small>{bot === "online" ? "In game" : "Offline"}</small>
            </div>
            {game?.mock && <span className="mock-note">Mock runtime</span>}
          </div>
          <button className="nav-item" onClick={onOpenWorkspace} title="Open the repository workspace">
            <svg viewBox="0 0 20 20" aria-hidden="true">{ICONS.workspace}</svg>
            Repository workspace
          </button>
        </div>
      </nav>

      <main className="studio-main">
        {error && <div className="alert page-alert">{error}</div>}
        {page === "build" && (
          <BuildPage
            mod={composing ? null : mod}
            running={running}
            lessons={lessons}
            onCreated={watchMod}
            onWatch={watchMod}
            onNew={newMod}
            onOpenCode={openMod}
          />
        )}
        {page === "mods" && <ModsPage mods={mods} mod={mod} setSelectedId={setSelectedId} onBuild={newMod} onWatch={watchMod} />}
        {page === "insights" && <InsightsPage mods={mods} lessons={lessons} />}
        {page === "neatlogs" && <NeatlogsPage mods={mods} onOpenMod={openMod} />}
        {page === "entire" && <EntirePage mods={mods} onOpenMod={openMod} />}
      </main>
    </div>
  );
}

import React from "react";
import { call, on } from "../../api.js";
import GamePane from "../game/GamePane.jsx";
import {
  AttemptTimeline,
  Empty,
  Icon,
  PHASES,
  PartnerStatus,
  PlanChecks,
  ROLE,
  SectionHead,
  Status,
  phaseIndex,
} from "./shared.jsx";

const EXAMPLES = [
  "A golden sword that launches any mob it hits into the sky with particles, with a 3 second cooldown.",
  "Arrows that explode on impact without breaking blocks, with a 5 second cooldown per player.",
  "Right-clicking with a blaze rod shoots a fireball where you look.",
];

const FLOW = [
  ["Spec", "Opus turns your idea into a plugin spec and a test plan."],
  ["Build", "Opus writes the Paper plugin, compiles it, and deploys it."],
  ["Playtest", "Sonnet joins the server as a player and runs every check."],
  ["Fix", "If a check fails, Opus reads the evidence and tries again."],
];

export default function BuildPage({ mod, running, lessons, onCreated, onWatch, onNew, onOpenCode }) {
  return mod ? (
    <RunView mod={mod} onNew={onNew} onOpenCode={onOpenCode} />
  ) : (
    <Composer running={running} lessons={lessons} onCreated={onCreated} onWatch={onWatch} />
  );
}

function Composer({ running, lessons, onCreated, onWatch }) {
  const [prompt, setPrompt] = React.useState("");
  const [seed, setSeed] = React.useState(false);
  const [busy, setBusy] = React.useState(false);
  const [error, setError] = React.useState("");

  const start = async () => {
    setBusy(true);
    setError("");
    try {
      const created = await call("studio:create", { prompt, seed });
      setPrompt("");
      onCreated(created.id);
    } catch (e) {
      setError(e.message);
    } finally {
      setBusy(false);
    }
  };

  const canStart = !busy && !running && (seed || prompt.trim().length >= 8);

  return (
    <div className="page compose-page">
      <div className="compose">
        <h1>What should your mod do?</h1>
        <p className="lede">Describe a gameplay idea. Benana writes the plugin, then an AI player tests it in a live server and fixes what breaks.</p>

        {running && (
          <button className="running-banner" onClick={() => onWatch(running.id)}>
            <Status status="running">Building</Status>
            <span>
              <strong>{running.name}</strong> is in progress. One mod builds at a time.
            </span>
            <span className="banner-cta">
              Watch <Icon name="arrow" size={14} />
            </span>
          </button>
        )}

        <div className={`composer ${seed ? "seeded" : ""}`}>
          <textarea
            aria-label="Describe a mod"
            value={prompt}
            disabled={seed}
            onChange={(e) => setPrompt(e.target.value)}
            onKeyDown={(e) => {
              if (e.key === "Enter" && (e.ctrlKey || e.metaKey) && canStart) start();
            }}
            placeholder="A golden sword that launches mobs into the sky…"
            rows={4}
          />
          <div className="composer-bar">
            <label className="toggle" title="Attempt 1 starts from a labeled buggy fixture. The playtester and fixer still run for real.">
              <input type="checkbox" checked={seed} onChange={(e) => setSeed(e.target.checked)} />
              <span className="switch" />
              Start from the seeded bug
            </label>
            <button className="btn primary" disabled={!canStart} onClick={start}>
              {busy ? "Starting…" : "Build and playtest"}
              <kbd>Ctrl ↵</kbd>
            </button>
          </div>
        </div>
        {error && <div className="alert">{error}</div>}

        <div className="examples">
          <span className="side-label">Try one</span>
          {EXAMPLES.map((ex) => (
            <button key={ex} onClick={() => setPrompt(ex)} disabled={seed}>
              <span>{ex}</span>
              <Icon name="arrow" size={14} />
            </button>
          ))}
        </div>

        <ol className="flow">
          {FLOW.map(([title, text], i) => (
            <li key={title}>
              <span className="flow-n">{i + 1}</span>
              <strong>{title}</strong>
              <p>{text}</p>
            </li>
          ))}
        </ol>

        {lessons.length > 0 && (
          <section className="lessons">
            <SectionHead title="What the fixer has learned" count={lessons.length} />
            <p className="meta">Every new builder reads these before it writes code.</p>
            <ul>
              {lessons
                .slice(-3)
                .reverse()
                .map((l) => (
                  <li key={l.at}>
                    <p>{l.lesson}</p>
                    <small>{l.mod}</small>
                  </li>
                ))}
            </ul>
          </section>
        )}
      </div>
    </div>
  );
}

function RunView({ mod, onNew, onOpenCode }) {
  const [feed, setFeed] = React.useState([]);
  const idRef = React.useRef(mod.id);
  idRef.current = mod.id;

  React.useEffect(() => {
    return on("studio:feed", ({ modId, item }) => {
      if (modId === idRef.current) setFeed((prev) => [...prev.slice(-599), item]);
    });
  }, []);

  React.useEffect(() => {
    setFeed([]);
    call("studio:get", { id: mod.id })
      .then((full) => setFeed(full.feed.slice(-600)))
      .catch(() => {});
  }, [mod.id]);

  return (
    <div className="page run-page">
      <header className="run-head">
        <div className="run-title">
          <div className="run-name">
            <h1>{mod.name}</h1>
            <Status status={mod.running ? "running" : mod.status} />
            {mod.seed && <span className="badge">Seeded bug</span>}
          </div>
          <p>{mod.prompt}</p>
        </div>
        <div className="page-actions">
          {mod.running && (
            <button className="btn danger" onClick={() => call("studio:stop", { id: mod.id })}>
              <Icon name="stop" size={14} />
              Stop run
            </button>
          )}
          {mod.repoDir && (
            <button className="btn" onClick={() => onOpenCode(mod.id)}>
              <Icon name="code" size={14} />
              View code
            </button>
          )}
          {!mod.running && (
            <button className="btn" onClick={onNew}>
              <Icon name="plus" size={14} />
              New mod
            </button>
          )}
        </div>
      </header>

      <Pipeline mod={mod} />
      {mod.error && <div className="alert">{mod.error}</div>}

      <div className="run-grid">
        <div className="run-stage">
          <GamePane showLog={false} />
          <Activity feed={feed} />
        </div>
        <aside className="run-side">
          <PlanChecks mod={mod} />
          <section className="block">
            <SectionHead title="Attempts" count={mod.attempts.length} />
            <AttemptTimeline mod={mod} />
          </section>
          <section className="block">
            <SectionHead title="Partners" />
            <PartnerStatus mod={mod} />
          </section>
        </aside>
      </div>
    </div>
  );
}

function Pipeline({ mod }) {
  const current = phaseIndex(mod);
  const done = mod.status === "passed";
  const failed = ["failed", "stopped"].includes(mod.status);
  return (
    <ol className="pipeline" aria-label="Pipeline">
      {PHASES.map(([key, label], i) => {
        const state = done || i < current ? "done" : i === current ? (failed ? "failed" : "current") : "todo";
        return (
          <li key={key} className={state}>
            <span className="pipe-icon">
              {state === "done" && <Icon name="check" size={11} />}
              {state === "failed" && <Icon name="x" size={11} />}
            </span>
            <span>{label}</span>
          </li>
        );
      })}
      <li className="pipe-meta">{mod.attempts.length ? `Attempt ${mod.attempts.length}` : "Not started"}</li>
    </ol>
  );
}

const clock = (ts) =>
  ts ? new Date(ts).toLocaleTimeString([], { hour: "2-digit", minute: "2-digit", second: "2-digit", hour12: false }) : "";

function Activity({ feed }) {
  const ref = React.useRef(null);
  const stick = React.useRef(true);
  const visible = feed.filter((f) => f.kind !== "session" && (f.kind !== "result" || f.isError || f.role === "playtester"));

  React.useEffect(() => {
    if (ref.current && stick.current) ref.current.scrollTop = ref.current.scrollHeight;
  }, [visible.length]);

  return (
    <section className="activity">
      <div className="activity-head">
        <h3>Agent activity</h3>
        <span className="meta">{visible.length} events</span>
      </div>
      <div
        className="activity-body"
        ref={ref}
        onScroll={(e) => {
          const el = e.currentTarget;
          stick.current = el.scrollHeight - el.scrollTop - el.clientHeight < 40;
        }}
      >
        {!visible.length && <Empty>Agent activity streams here as the run progresses.</Empty>}
        {visible.slice(-250).map((f, i) => (
          <div key={`${f.at}-${i}`} className={`event ${f.kind} ${f.isError ? "error" : ""}`}>
            <time>{clock(f.at)}</time>
            <span className={`event-role ${f.role}`}>
              {ROLE[f.role] || f.role}
              {f.attempt ? <small>#{f.attempt}</small> : null}
            </span>
            <div className="event-text">
              {f.kind === "tool" ? (
                <>
                  <code>{f.name}</code>
                  <span>{f.summary}</span>
                </>
              ) : f.kind === "result" ? (
                <>
                  <code>{f.name}</code>
                  <span className="result">{f.text.slice(0, 300)}</span>
                </>
              ) : (
                <span>{f.text}</span>
              )}
            </div>
          </div>
        ))}
      </div>
    </section>
  );
}

