import React from "react";
import { call } from "../../api.js";
import { Empty, PageHead, ROLE, SectionHead, allSessions, fmtDuration, fmtMoney, sessionMs, shortModel } from "./shared.jsx";

const CHECK_LIMIT = 25;

export default function NeatlogsPage({ mods, onOpenMod }) {
  const [status, setStatus] = React.useState(null);
  const [evidence, setEvidence] = React.useState({});
  const [selectedKey, setSelectedKey] = React.useState(null);
  const [checking, setChecking] = React.useState(false);
  const sessions = React.useMemo(() => allSessions(mods), [mods]);
  const linked = sessions.filter((s) => s.sessionId);
  const selected = sessions.find((s) => s.key === selectedKey) || null;
  const checked = Object.keys(evidence).length;
  const matched = Object.values(evidence).filter((e) => e?.matched).length;

  React.useEffect(() => {
    call("studio:partners")
      .then((p) => setStatus(p.neatlogs))
      .catch((e) => setStatus({ configured: true, ok: false, error: e.message }));
  }, []);

  const check = React.useCallback(async (session) => {
    if (!session?.sessionId) return;
    try {
      const result = await call("studio:evidence", { sessionId: session.sessionId });
      setEvidence((prev) => ({ ...prev, [session.key]: result }));
    } catch (e) {
      setEvidence((prev) => ({ ...prev, [session.key]: { configured: true, matched: false, traces: [], error: e.message } }));
    }
  }, []);

  React.useEffect(() => {
    if (selected && !evidence[selected.key]) check(selected);
  }, [selected?.key]);

  const checkAll = async () => {
    setChecking(true);
    for (const s of linked.filter((x) => !evidence[x.key]).slice(0, CHECK_LIMIT)) await check(s);
    setChecking(false);
  };

  const ev = selected ? evidence[selected.key] : null;
  const state = !status ? "idle" : status.configured === false ? "idle" : status.ok ? "passed" : "failed";

  return (
    <div className="page">
      <PageHead title="Neatlogs" sub="Every builder, playtester, and fixer session, linked to its trace.">
        <button className="btn" onClick={checkAll} disabled={checking || !linked.length || checked >= linked.length}>
          {checking ? "Checking traces…" : checked >= linked.length && linked.length ? "All traces checked" : `Check ${Math.min(linked.length - checked, CHECK_LIMIT)} traces`}
        </button>
      </PageHead>

      <div className="connection">
        <span className={`dot ${state}`} />
        <strong>
          {!status
            ? "Checking Neatlogs…"
            : status.configured === false
              ? "Neatlogs is not configured"
              : status.ok
                ? "Connected"
                : "Unreachable"}
        </strong>
        <span className="meta">
          {status?.configured === false
            ? "Add NEATLOGS_API_KEY and NEATLOGS_PROJECT_ID to .env to link sessions to traces."
            : status?.error || "Neatlogs hooks in each mod repository trace every agent session."}
        </span>
      </div>

      <section className="kpis three">
        <div className="kpi">
          <span>Agent sessions</span>
          <strong>{sessions.length}</strong>
          <small>across {mods.length} mods</small>
        </div>
        <div className="kpi">
          <span>With a session ID</span>
          <strong>{linked.length}</strong>
          <small>Neatlogs can attribute these</small>
        </div>
        <div className="kpi">
          <span>Traces matched</span>
          <strong>{checked ? matched : "—"}</strong>
          <small>{checked ? `of ${checked} checked` : "Not checked yet"}</small>
        </div>
      </section>

      <div className="split">
        <section className="panel">
          {sessions.length ? (
            <table className="table selectable">
              <thead>
                <tr>
                  <th>Mod</th>
                  <th>Step</th>
                  <th>Role</th>
                  <th>Model</th>
                  <th className="num">Time</th>
                  <th className="num">Cost</th>
                  <th>Trace</th>
                </tr>
              </thead>
              <tbody>
                {sessions.map((s) => {
                  const e = evidence[s.key];
                  return (
                    <tr key={s.key} className={s.key === selectedKey ? "selected" : ""} onClick={() => setSelectedKey(s.key)}>
                      <td className="strong">{s.mod.name}</td>
                      <td>{s.attemptN ? `Attempt ${s.attemptN}` : "Spec"}</td>
                      <td>{ROLE[s.role] || s.role}</td>
                      <td className="mono muted">{shortModel(s.model)}</td>
                      <td className="num">{fmtDuration(sessionMs(s)) || "—"}</td>
                      <td className="num">{fmtMoney(s.usage?.costUsd)}</td>
                      <td>
                        {!s.sessionId ? (
                          <span className="muted">No session ID</span>
                        ) : e ? (
                          <span className={`partner-link static neatlogs ${e.matched ? "" : "off"}`}>
                            <i />
                            {e.matched ? `${e.traces.length} trace${e.traces.length === 1 ? "" : "s"}` : "No trace"}
                          </span>
                        ) : (
                          <span className="muted">Not checked</span>
                        )}
                      </td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          ) : (
            <Empty>Agent sessions appear here after a mod starts building.</Empty>
          )}
        </section>

        <aside className="panel pad detail-card">
          {!selected && <Empty>Select a session to see its trace.</Empty>}
          {selected && (
            <>
              <SectionHead title={ROLE[selected.role] || selected.role}>
                <button className="link" onClick={() => onOpenMod(selected.mod.id)}>
                  Open mod
                </button>
              </SectionHead>
              <p className="meta">
                {selected.mod.name} · {selected.attemptN ? `attempt ${selected.attemptN}` : "spec"} · {shortModel(selected.model)}
              </p>
              <dl className="facts stacked">
                <div>
                  <dt>Session ID</dt>
                  <dd className="mono">{selected.sessionId || "Not reported"}</dd>
                </div>
                <div>
                  <dt>Outcome</dt>
                  <dd>{selected.ok === false ? selected.error || "Failed" : selected.endedAt ? "Completed" : "Running"}</dd>
                </div>
                <div>
                  <dt>Tokens</dt>
                  <dd>
                    {(selected.usage?.inputTokens || 0).toLocaleString()} in · {(selected.usage?.outputTokens || 0).toLocaleString()} out
                  </dd>
                </div>
              </dl>
              {!ev && <Empty>Looking up the trace…</Empty>}
              {ev?.error && <div className="alert">{ev.error}</div>}
              {ev && !ev.error && <p className="meta">{ev.matchReason || (ev.matched ? "Trace matched." : "No trace yet.")}</p>}
              {ev?.traces?.map((t, i) => (
                <div className="trace" key={t.traceId || t.trace_id || i}>
                  <div className="trace-head">
                    <strong>{t.traceName || t.name || "trace"}</strong>
                    {t.durationMs != null && <span className="meta">{fmtDuration(t.durationMs)}</span>}
                  </div>
                  <small className="mono muted">{t.traceId || t.trace_id || t.id}</small>
                  <ol className="spans">
                    {(t.spans || []).slice(0, 25).map((sp, j) => {
                      const failed = sp.status === "error" || sp.status_code === "ERROR";
                      return (
                        <li key={j} className={failed ? "failed" : ""}>
                          <span>{sp.spanName || sp.name || sp.span_name || "span"}</span>
                          {sp.failure && <small>{sp.failure}</small>}
                        </li>
                      );
                    })}
                  </ol>
                </div>
              ))}
            </>
          )}
        </aside>
      </div>
    </div>
  );
}

import React from "react";
import { call, ago } from "../../api.js";
import { Empty, Icon, PageHead, ROLE, SectionHead, Status, shortSha } from "./shared.jsx";

const pick = (c, ...keys) => keys.map((k) => c?.[k]).find((v) => v != null && v !== "") ?? "";

export default function EntirePage({ mods, onOpenMod }) {
  const repos = mods.filter((m) => m.repoDir);
  const [selectedId, setLocalId] = React.useState(null);
  const mod = repos.find((m) => m.id === selectedId) || repos[0] || null;
  const [cps, setCps] = React.useState(null);

  React.useEffect(() => {
    setCps(null);
    if (!mod) return;
    call("studio:checkpoints", { id: mod.id })
      .then(setCps)
      .catch((e) => setCps({ ok: false, items: [], error: e.message }));
  }, [mod?.id, mod?.attempts.length]);

  const commits = mod
    ? mod.attempts.flatMap((a) =>
        [
          a.commit?.sha && {
            sha: a.commit.sha,
            checkpoint: a.commit.checkpoint,
            label: `Attempt ${a.n}`,
            role: a.role === "seeded" ? "Seeded fixture" : ROLE[a.role],
            ok: !a.failure || a.failure.kind !== "build",
          },
          a.playtestCommit?.sha && {
            sha: a.playtestCommit.sha,
            checkpoint: a.playtestCommit.checkpoint,
            label: `Playtest ${a.n}`,
            role: a.verdict?.passed ? "Checks passed" : "Checks failed",
            ok: Boolean(a.verdict?.passed),
          },
        ].filter(Boolean),
      )
    : [];
  const linked = commits.filter((c) => c.checkpoint).length;
  const entireOn = repos.some((m) => m.partners?.entire?.enabled);

  return (
    <div className="page">
      <PageHead title="Entire" sub="Each agent commit, linked to the checkpoint of the session that wrote it." />

      <div className="connection">
        <span className={`dot ${entireOn ? "passed" : "idle"}`} />
        <strong>{entireOn ? "Enabled in mod repositories" : repos.length ? "Not set up" : "No repositories yet"}</strong>
        <span className="meta">
          Every agent commit carries an Entire-Checkpoint trailer. The fixer reads these checkpoints before it changes the plugin.
        </span>
      </div>

      {!repos.length ? (
        <section className="panel pad">
          <Empty>No mod repositories yet. Each mod gets its own git repository with Entire enabled.</Empty>
        </section>
      ) : (
        <div className="split entire-split">
          <section className="panel">
            <div className="panel-head">
              <SectionHead title="Repositories" count={repos.length} />
            </div>
            <div className="list">
              {repos.map((m) => {
                const n = m.attempts.reduce((k, a) => k + (a.commit?.sha ? 1 : 0) + (a.playtestCommit?.sha ? 1 : 0), 0);
                return (
                  <button key={m.id} className={`list-row ${m.id === mod?.id ? "active" : ""}`} onClick={() => setLocalId(m.id)}>
                    <span className="list-main">
                      <strong>{m.name}</strong>
                      <small>
                        {n} commit{n === 1 ? "" : "s"} · {ago(m.createdAt)} ago
                      </small>
                    </span>
                    <span className={`partner-dot entire ${m.partners?.entire?.enabled ? "" : "off"}`} title={m.partners?.entire?.enabled ? "Entire enabled" : "Entire off"} />
                  </button>
                );
              })}
            </div>
          </section>

          <section className="panel pad">
            {mod && (
              <>
                <header className="detail-head">
                  <div className="detail-title">
                    <div className="run-name">
                      <h2>{mod.name}</h2>
                      <Status status={mod.running ? "running" : mod.status} />
                    </div>
                    <p>
                      {linked} of {commits.length} commits linked to a checkpoint
                    </p>
                  </div>
                  <div className="page-actions">
                    <button className="btn" onClick={() => onOpenMod(mod.id)}>
                      <Icon name="code" size={14} />
                      Open mod
                    </button>
                    <button className="btn" onClick={() => call("open-path", mod.repoDir)}>
                      <Icon name="folder" size={14} />
                      Repository
                    </button>
                  </div>
                </header>

                <section className="block">
                  <SectionHead title="Commit history" count={commits.length} />
                  <ol className="commits">
                    {commits.map((c) => (
                      <li key={c.sha} className={c.ok ? "ok" : "bad"}>
                        <span className="commit-node" />
                        <div className="commit-main">
                          <strong>{c.label}</strong>
                          <span className="meta">{c.role}</span>
                        </div>
                        <code className="sha static">{shortSha(c.sha)}</code>
                        {c.checkpoint ? (
                          <span className="partner-link static entire">
                            <i />
                            {c.checkpoint.slice(0, 12)}
                          </span>
                        ) : (
                          <span className="muted">No checkpoint</span>
                        )}
                      </li>
                    ))}
                    {!commits.length && <Empty>Commits appear here as each attempt finishes.</Empty>}
                  </ol>
                </section>

                <section className="block">
                  <SectionHead title="Checkpoints in this repository" count={cps?.ok ? cps.items.length : null} />
                  {!cps && <Empty>Loading checkpoints…</Empty>}
                  {cps && !cps.ok && <div className="alert">{cps.error || "Entire could not list checkpoints."}</div>}
                  {cps?.ok && cps.items.length === 0 && <Empty>No checkpoints yet.</Empty>}
                  {cps?.ok && cps.items.length > 0 && (
                    <table className="table">
                      <thead>
                        <tr>
                          <th>Checkpoint</th>
                          <th>Message</th>
                          <th>Session</th>
                          <th>Agent</th>
                        </tr>
                      </thead>
                      <tbody>
                        {cps.items.map((c, i) => (
                          <tr key={pick(c, "checkpoint_id", "id") || i}>
                            <td className="mono">{String(pick(c, "checkpoint_id", "checkpointId", "id")).slice(0, 12)}</td>
                            <td>{pick(c, "message", "title", "summary")}</td>
                            <td className="mono muted">{String(pick(c, "session_id", "sessionId")).slice(0, 14)}</td>
                            <td>{pick(c, "agent")}</td>
                          </tr>
                        ))}
                      </tbody>
                    </table>
                  )}
                </section>
              </>
            )}
          </section>
        </div>
      )}
    </div>
  );
}

