}
.studio .daily .grid {
  stroke: var(--line);
  stroke-dasharray: 2 4;
}
.studio .daily .tick {
  fill: var(--text-3);
  font-size: 11px;
}
.studio .daily .hit {
  fill: transparent;
}
.studio .daily .hover-band {
  fill: rgba(255, 255, 255, 0.04);
}
.studio .daily .passed {
  fill: var(--good);
}
.studio .daily .failed {
  fill: var(--bad);
}
.studio .daily .running {
  fill: var(--accent);
}
.studio .tooltip {
  position: absolute;
  top: 0;
  z-index: 2;
  display: grid;
  gap: 3px;
  min-width: 140px;
  padding: 9px 11px;
  border: 1px solid var(--line-strong);
  border-radius: 8px;
  background: #1a1c21;
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.45);
  font-size: 12px;
  pointer-events: none;
  transform: translate(-50%, -8px);
}
.studio .tooltip strong {
  margin-bottom: 2px;
  font-weight: 600;
}
.studio .tooltip span {
  display: flex;
  align-items: center;
  gap: 7px;
  color: var(--text-2);
}
.studio .tooltip i {
  width: 8px;
  height: 8px;
  border-radius: 2px;
}
.studio .tooltip i.passed {
  background: var(--good);
}
.studio .tooltip i.failed {
  background: var(--bad);
}
.studio .tooltip i.running {
  background: var(--accent);
}
.studio .tooltip b {
  margin-left: auto;
  color: var(--text);
