  align-items: center;
  gap: 12px;
  color: var(--text-2);
  font-size: 12.5px;
}
.studio .hbars strong {
  color: var(--text);
  font-weight: 600;
  text-align: right;
  font-variant-numeric: tabular-nums;
}
.studio .coverage-row {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 12px;
}
.studio .coverage {
