  border: 1px solid var(--line);
  border-radius: 8px;
}
.studio .coverage .partner-dot {
  margin-top: 6px;
}
.studio .coverage strong {
  display: block;
  font-size: 20px;
  font-weight: 600;
  line-height: 1.2;
  font-variant-numeric: tabular-nums;
}
.studio .coverage span {
  display: block;
  color: var(--text);
  font-size: 12.5px;
}
.studio .coverage small {
  color: var(--text-3);
  font-size: 11.5px;
}

