}
.studio .commits li.bad .commit-node {
  border-color: var(--bad);
}
.studio .commit-main {
  display: flex;
  flex: 1;
  align-items: baseline;
  gap: 10px;
  min-width: 0;
}
.studio .commit-main strong {
  font-weight: 500;
}

@media (max-width: 1360px) {
  .studio .run-grid {
    grid-template-columns: minmax(0, 1fr) 340px;
  }
  .studio .kpis {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }
  .studio .kpi:nth-child(4) {
    border-left: 0;
