  color: var(--text-2);
  font-size: 14px;
  line-height: 1.6;
}
.studio .suggestions {
  display: grid;
  gap: 8px;
  margin-top: 8px;
}
.studio .suggestions button {
  display: flex;
  align-items: flex-start;
  gap: 10px;
  padding: 11px 13px;
  border: 1px solid var(--line);
  border-radius: 10px;
  background: var(--panel);
  color: var(--text-2);
  font-size: 13px;
  line-height: 1.5;
  text-align: left;
  transition: border-color 0.12s, color 0.12s, background 0.12s;
}
.studio .suggestions button .ico {
  margin-top: 2px;
  color: var(--accent);
}
.studio .suggestions button:hover {
  border-color: var(--line-strong);
  background: var(--raised);
  color: var(--text);
}
.studio .welcome-lessons {
  margin-top: 10px;
  padding-top: 14px;
  border-top: 1px solid var(--line);
}
.studio .welcome-lessons .side-label {
  padding: 0 0 4px;
}
.studio .welcome-lessons p {
  color: var(--text-2);
  font-size: 12.5px;
}

/* Live testing panel */

.studio .test-panel {
  display: grid;
  grid-template-rows: minmax(0, 1.15fr) minmax(220px, 1fr);
  gap: 12px;
  min-width: 0;
  min-height: 0;
  padding: 12px;
  background: var(--bg);
}
.studio .lanes {
  display: grid;
  grid-template-columns: minmax(0, 1.35fr) minmax(0, 1fr);
  gap: 12px;
  min-height: 0;
}
.studio .lane-stack {
  display: grid;
  grid-template-rows: minmax(0, 1fr) minmax(0, 1fr);
  gap: 12px;
  min-height: 0;
}
.studio .lane {
  position: relative;
  display: flex;
  flex-direction: column;
  min-width: 0;
  min-height: 0;
  border: 1px solid var(--line);
  border-radius: 10px;
  background: var(--panel);
  overflow: hidden;
}
.studio .lane-head {
  display: flex;
  flex: none;
  align-items: center;
  gap: 8px;
  height: 36px;
  padding: 0 12px;
  border-bottom: 1px solid var(--line);
  font-size: 12px;
}
.studio .lane-head strong {
  font-size: 12.5px;
  font-weight: 600;
}
.studio .lane-mark {
  width: 8px;
  height: 8px;
  border-radius: 2px;
  background: var(--text-3);
}
.studio .lane-mark.server {
  background: var(--good);
}
.studio .lane-mark.neatlogs {
  background: var(--neatlogs);
}
.studio .lane-mark.entire {
  background: var(--entire);
}
.studio .lane-live {
  display: none;
  align-items: center;
  gap: 5px;
  padding: 0 6px;
  border-radius: 99px;
  background: var(--good-soft);
  color: var(--good-text);
  font-size: 10.5px;
  font-weight: 600;
  line-height: 17px;
}
.studio .lane-live.on {
  display: inline-flex;
}
.studio .lane-live::before {
  content: "";
  width: 5px;
  height: 5px;
  border-radius: 50%;
  background: currentColor;
  animation: blink 1.4s ease-in-out infinite;
}
@keyframes blink {
  50% {
    opacity: 0.25;
  }
}
.studio .lane-meta {
  margin-left: auto;
  color: var(--text-3);
  font-size: 11.5px;
  white-space: nowrap;
}
.studio .lane-meta b {
  font-weight: 500;
}
.studio .lane-meta b.warn {
  color: var(--warn);
}
.studio .lane-meta b.error {
  color: var(--bad-text);
}
.studio .lane-body {
  flex: 1;
  min-height: 0;
  padding: 8px;
  overflow-y: auto;
}
.studio .lane-body > * {
  animation: rise 0.3s ease-out both;
}
.studio .lane-empty {
  padding: 6px 4px;
  color: var(--text-3);
  font-size: 12px;
}

.studio .lane-body.log {
  padding: 6px 0;
  background: #0d0e11;
  font-family: var(--mono);
  font-size: 11.5px;
  line-height: 1.6;
}
.studio .log-line {
  display: grid;
  grid-template-columns: 60px minmax(0, 1fr);
  gap: 8px;
  padding: 1px 12px;
  border-left: 2px solid transparent;
  color: #b9bcc4;
}
.studio .log-line time {
  color: #4f535c;
}
.studio .log-text {
  min-width: 0;
  overflow-wrap: anywhere;
}
.studio .log-line.warn {
  border-left-color: var(--warn);
  background: rgba(240, 180, 41, 0.05);
  color: #f3cf7a;
}
.studio .log-line.error {
  border-left-color: var(--bad);
  background: rgba(229, 72, 77, 0.07);
  color: #ff9a9d;
}
.studio .log-line.mine {
  border-left-color: var(--accent);
  color: var(--text);
}
.studio .log-src,
.studio .log-plugin {
  margin-right: 6px;
  padding: 0 5px;
  border-radius: 4px;
  font-size: 10.5px;
  font-style: normal;
}
.studio .log-plugin {
  background: rgba(245, 200, 76, 0.12);
  color: var(--accent);
}
.studio .log-src {
  background: rgba(143, 199, 245, 0.12);
  color: #8fc7f5;
}
.studio .log-src.benana {
  background: rgba(245, 200, 76, 0.12);
  color: var(--accent);
}
.studio .log-src.chat {
  background: rgba(168, 220, 194, 0.12);
  color: #a8dcc2;
}
.studio .lane .jump {
  bottom: 10px;
}

.studio .trace-card,
.studio .cp-card {
  display: grid;
  gap: 5px;
  padding: 9px 10px;
  border: 1px solid var(--line);
  border-radius: 8px;
  background: var(--bg);
}
.studio .trace-card + .trace-card,
.studio .cp-card + .cp-card {
  margin-top: 6px;
}
.studio .trace-card.live {
  border-color: rgba(79, 184, 208, 0.35);
}
.studio .trace-card.matched {
  border-color: rgba(79, 184, 208, 0.2);
}
.studio .trace-row {
  display: flex;
  align-items: center;
  gap: 7px;
  font-size: 12.5px;
}
.studio .trace-row strong {
  font-weight: 600;
}
.studio .trace-row .lane-meta {
  margin-left: 0;
}
.studio .trace-state {
  margin-left: auto;
  color: var(--text-2);
  font-size: 11.5px;
  white-space: nowrap;
}
.studio .trace-card.live .trace-state {
  color: var(--neatlogs);
}
.studio .trace-sub {
  display: flex;
  gap: 10px;
  color: var(--text-3);
  font-size: 11px;
}
.studio .trace-sub code {
  font-family: var(--mono);
}
.studio .role-dot {
  flex: none;
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: var(--text-3);
}
.studio .role-dot.spec {
  background: #a8dcc2;
}
.studio .role-dot.builder {
  background: #c7b4fa;
}
.studio .role-dot.playtester {
  background: #8fc7f5;
}
.studio .role-dot.fixer {
  background: #f5b98f;
}
.studio .trace-progress {
  position: relative;
  height: 3px;
  border-radius: 99px;
  background: rgba(79, 184, 208, 0.12);
  overflow: hidden;
}
.studio .trace-progress::after {
  content: "";
  position: absolute;
  inset: 0;
  width: 35%;
  border-radius: 99px;
  background: var(--neatlogs);
  animation: sweep 1.6s ease-in-out infinite;
}
@keyframes sweep {
  from {
    transform: translateX(-100%);
  }
  to {
    transform: translateX(290%);
  }
}
.studio .span-strip {
  display: flex;
  gap: 2px;
  height: 6px;
}
.studio .span-strip i {
  flex: 1;
  border-radius: 2px;
  background: rgba(79, 184, 208, 0.55);
  animation: rise 0.3s ease-out both;
}
.studio .span-strip i.err {
  background: var(--bad);
}
.studio .trace-error {
  color: var(--bad-text);
  font-size: 11.5px;
}

.studio .cp-card strong {
  font-size: 12.5px;
  font-weight: 500;
}
.studio .cp-card.read {
  border-style: dashed;
}
.studio .cp-link {
  display: flex;
  align-items: center;
  gap: 6px;
}
.studio .sha-chip,
.studio .cp-chip {
  padding: 1px 6px;
  border-radius: 5px;
  font-family: var(--mono);
  font-size: 11px;
}
.studio .sha-chip {
  background: var(--raised);
  color: var(--text);
}
.studio .cp-chip {
  background: rgba(167, 139, 250, 0.14);
  color: #c4b1fc;
}
.studio .cp-arrow {
  width: 14px;
  height: 1px;
  background: var(--line-strong);
}

.studio .lesson-list {
  display: grid;
  margin: 10px 0 0;
  padding: 0;
  list-style: none;
}
.studio .lesson-list li {
  padding: 10px 0;
  border-top: 1px solid var(--line);
}
.studio .lesson-list li p {
  color: var(--text);
  font-size: 12.5px;
}
.studio .lesson-list li small {
  color: var(--text-3);
  font-size: 11.5px;
}

EOF
python - <<'EOF'
