input.content:
/* ---------- Build: chat + live testing ---------- */

.studio .btn.sm {
  height: 28px;
  padding: 0 10px;
  gap: 6px;
  font-size: 12.5px;
}

.studio .spinner {
  display: inline-block;
  flex: none;
  width: 13px;
  height: 13px;
  border: 1.6px solid rgba(245, 200, 76, 0.25);
  border-top-color: var(--accent);
  border-radius: 50%;
  animation: spin 0.8s linear infinite;
}
.studio .spinner.dark {
  border-color: rgba(0, 0, 0, 0.2);
  border-top-color: #0b0c0e;
}
@keyframes rise {
  from {
    opacity: 0;
    transform: translateY(6px);
  }
  to {
    opacity: 1;
    transform: none;
  }
}
@keyframes pop {
  0% {
    transform: scale(0.6);
  }
  70% {
    transform: scale(1.12);
  }
  100% {
    transform: scale(1);
  }
}
@keyframes blink {
  50% {
    opacity: 0.25;
  }
}
@keyframes sweep {
  from {
    transform: translateX(-100%);
  }
  to {
    transform: translateX(290%);
  }
}

.studio .build-chat {
  display: grid;
  flex: 1;
  grid-template-columns: minmax(400px, 0.85fr) minmax(0, 1.15fr);
  min-height: 0;
}

.studio .chat {
  position: relative;
  display: flex;
  flex-direction: column;
  min-width: 0;
  min-height: 0;
  border-right: 1px solid var(--line);
}
.studio .chat-head {
  display: flex;
  flex: none;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  height: 52px;
  padding: 0 16px 0 22px;
  border-bottom: 1px solid var(--line);
}
.studio .chat-title {
  display: flex;
  align-items: center;
  gap: 10px;
  min-width: 0;
}
.studio .chat-title strong {
  overflow: hidden;
  font-size: 14px;
  font-weight: 600;
  letter-spacing: -0.01em;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.studio .thread {
  position: relative;
  flex: 1;
  min-height: 0;
  overflow-y: auto;
}
.studio .thread-inner {
  display: flex;
  flex-direction: column;
  gap: 18px;
  max-width: 760px;
  margin: 0 auto;
  padding: 24px 24px 28px;
}
.studio .thread-inner > * {
  animation: rise 0.28s ease-out both;
}

.studio .msg-user {
  display: flex;
  justify-content: flex-end;
}
.studio .bubble {
  max-width: 86%;
  padding: 10px 14px;
  border: 1px solid var(--line);
  border-radius: 14px 14px 4px 14px;
  background: var(--raised);
  color: var(--text);
  font-size: 13.5px;
  line-height: 1.55;
  white-space: pre-wrap;
}

.studio .turn {
  display: grid;
  gap: 8px;
}
.studio .turn-head {
  display: flex;
  align-items: center;
  gap: 9px;
}
.studio .turn-head strong {
  font-size: 13px;
  font-weight: 600;
}
.studio .turn-body,
.studio .turn-cont {
  display: grid;
  gap: 10px;
  padding-left: 31px;
}
.studio .turn-cont {
  margin-top: -8px;
}
.studio .avatar {
  display: grid;
  flex: none;
  place-items: center;
  width: 22px;
  height: 22px;
  border-radius: 6px;
  background: var(--raised);
  color: var(--text);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: -0.02em;
}
.studio .avatar.benana {
  background: var(--accent);
  color: #1b1503;
}
.studio .avatar.spec {
  background: rgba(168, 220, 194, 0.16);
  color: #a8dcc2;
}
.studio .avatar.builder {
  background: rgba(199, 180, 250, 0.16);
  color: #c7b4fa;
}
.studio .avatar.playtester {
  background: rgba(143, 199, 245, 0.16);
  color: #8fc7f5;
}
.studio .avatar.fixer {
  background: rgba(245, 185, 143, 0.16);
  color: #f5b98f;
}

.studio .prose {
  color: var(--text);
  font-size: 13.5px;
  line-height: 1.65;
}
.studio .prose p + p,
.studio .prose p + ul,
.studio .prose ul + p {
  margin-top: 8px;
}
.studio .prose ul {
  margin: 6px 0 0;
  padding-left: 18px;
}
.studio .prose li {
  padding: 2px 0;
}
.studio .prose li::marker {
  color: var(--text-3);
}
.studio .prose strong {
  font-weight: 600;
}
.studio .prose code {
  padding: 1px 5px;
  border-radius: 4px;
  background: var(--raised);
  font-family: var(--mono);
  font-size: 12px;
}

.studio .checklist {
  overflow: hidden;
  border: 1px solid var(--line);
  border-radius: 10px;
  background: var(--panel);
}
.studio .checklist-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 10px 14px;
  border-bottom: 1px solid var(--line);
}
.studio .checklist-head strong {
  font-size: 12.5px;
  font-weight: 600;
}
.studio .checklist ul {
  margin: 0;
  padding: 6px 0;
  list-style: none;
}
.studio .checklist li {
  display: grid;
  grid-template-columns: 18px auto minmax(0, 1fr);
  align-items: center;
  column-gap: 10px;
  padding: 6px 14px;
  font-size: 13px;
  transition: background 0.2s;
}
.studio .checklist li.tall {
  grid-template-columns: 18px minmax(0, 1fr);
  row-gap: 1px;
  align-items: start;
  padding: 8px 14px;
}
.studio .checklist li.tall > :first-child {
  grid-row: span 2;
  margin-top: 1px;
}
.studio .step-label {
  color: var(--text);
  font-weight: 500;
  white-space: nowrap;
}
.studio .step-detail {
  overflow: hidden;
  color: var(--text-3);
  font-size: 12px;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.studio li.tall .step-label {
  white-space: normal;
}
.studio li.tall .step-detail {
  white-space: normal;
  line-height: 1.5;
}
.studio .checklist li.done .step-label {
  color: var(--text-2);
}
.studio .checklist li.todo .step-label,
.studio .checklist li.skipped .step-label {
  color: var(--text-3);
}
.studio .checklist li.active {
  background: rgba(245, 200, 76, 0.05);
}
.studio .checklist li.active .step-label {
  color: var(--text);
  font-weight: 600;
}
.studio .checklist li.failed .step-label {
  color: var(--bad-text);
}
.studio .checklist li.failed .step-detail {
  color: var(--text-2);
}
.studio .step-icon {
  display: inline-grid;
  place-items: center;
  width: 18px;
  height: 18px;
  border: 1.5px solid var(--line-strong);
  border-radius: 50%;
  color: var(--text-3);
}
.studio .step-icon .ico {
  stroke-width: 2.4;
}
.studio .step-icon.done {
  border-color: transparent;
  background: var(--good-soft);
  color: var(--good);
  animation: pop 0.35s ease-out;
}
.studio .step-icon.failed {
  border-color: transparent;
  background: var(--bad-soft);
  color: var(--bad);
}
.studio .step-icon.active {
  border: 0;
}
.studio .step-icon.skipped {
  border-style: dashed;
}

.studio .worklog {
  display: grid;
  gap: 1px;
  padding: 6px 0 6px 12px;
  border-left: 1.5px solid var(--line-strong);
}
.studio .worklog.live {
  border-left-color: rgba(245, 200, 76, 0.45);
}
.studio .work-row {
  display: flex;
  align-items: center;
  gap: 8px;
  min-width: 0;
  padding: 3px 0;
  color: var(--text-3);
  font-size: 12.5px;
  animation: rise 0.25s ease-out both;
}
.studio .work-row .ico {
  color: var(--text-3);
}
.studio .work-row code {
  flex: none;
  color: var(--text-2);
  font-family: var(--mono);
  font-size: 12px;
}
.studio .work-args,
.studio .work-out {
  min-width: 0;
  overflow: hidden;
  font-family: var(--mono);
  font-size: 11.5px;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.studio .work-row.check {
  color: var(--text-2);
}
.studio .work-row.check strong {
  color: var(--text);
  font-weight: 500;
}
.studio .work-row.result {
  padding-left: 4px;
}
.studio .work-row.result.error .work-out {
  color: var(--bad-text);
}
.studio .work-arrow {
  color: var(--text-3);
}
.studio .worklog-more {
  justify-self: start;
  margin-bottom: 2px;
  padding: 0;
  border: 0;
  background: none;
  color: var(--text-3);
  font-size: 12px;
}
.studio .worklog-more:hover {
  color: var(--text);
}

.studio .phase-line {
  display: flex;
  align-items: center;
  gap: 10px;
  color: var(--text-2);
  font-size: 12.5px;
}
.studio .phase-line::after {
  content: "";
  flex: 1;
  height: 1px;
  background: var(--line);
}
.studio .phase-line.current {
  color: var(--text);
  font-weight: 500;
}
.studio .note-line {
  display: flex;
  align-items: center;
  gap: 8px;
  padding-left: 31px;
  color: var(--text-3);
  font-size: 12px;
}
.studio .note-line.entire .ico {
  color: var(--entire);
}
.studio .alert-card {
  display: flex;
  gap: 12px;
  padding: 12px 14px;
  border: 1px solid rgba(229, 72, 77, 0.25);
  border-radius: 10px;
  background: var(--bad-soft);
}
.studio .alert-card strong {
  color: var(--bad-text);
  font-size: 13px;
  font-weight: 600;
}
.studio .alert-card p {
  margin-top: 2px;
  color: var(--text-2);
  font-size: 12.5px;
}

.studio .result-card {
  display: grid;
  gap: 12px;
  padding: 16px;
  border: 1px solid rgba(76, 195, 138, 0.28);
  border-radius: 12px;
  background: linear-gradient(180deg, rgba(76, 195, 138, 0.1), rgba(76, 195, 138, 0.02));
}
.studio .result-card.failed,
.studio .result-card.stopped {
  border-color: rgba(229, 72, 77, 0.28);
  background: linear-gradient(180deg, rgba(229, 72, 77, 0.1), rgba(229, 72, 77, 0.02));
}
.studio .result-top {
  display: flex;
  gap: 12px;
}
.studio .result-top strong {
  font-size: 14px;
  font-weight: 600;
}
.studio .result-top p {
  margin-top: 2px;
  color: var(--text-2);
  font-size: 12.5px;
}
.studio .result-icon {
  display: grid;
  flex: none;
  place-items: center;
  width: 32px;
  height: 32px;
  border-radius: 50%;
  background: var(--good);
  color: #08140e;
}
.studio .result-icon .ico {
  stroke-width: 2.4;
}
.studio .result-card.failed .result-icon,
.studio .result-card.stopped .result-icon {
  background: var(--bad);
  color: #fff;
}
.studio .result-actions {
  display: flex;
  gap: 8px;
}

.studio .jump {
  position: absolute;
  bottom: 14px;
  left: 50%;
  z-index: 3;
  height: 28px;
  padding: 0 12px;
  border: 1px solid var(--line-strong);
  border-radius: 99px;
  background: #1a1c21;
  box-shadow: 0 6px 18px rgba(0, 0, 0, 0.45);
  color: var(--text);
  font-size: 12px;
  transform: translateX(-50%);
}

/* Composer */

.studio .composer-wrap {
  display: grid;
  flex: none;
  gap: 8px;
  padding: 0 20px 18px;
}
.studio .composer-wrap > * {
  width: 100%;
  max-width: 760px;
  margin: 0 auto;
}
.studio .dock {
  display: flex;
  align-items: center;
  gap: 11px;
  padding: 9px 12px;
  border: 1px solid rgba(245, 200, 76, 0.22);
  border-radius: 10px;
  background: linear-gradient(90deg, rgba(245, 200, 76, 0.09), rgba(245, 200, 76, 0.02));
  color: var(--text-2);
  font-size: 12.5px;
  text-align: left;
}
.studio .dock-text {
  display: grid;
  flex: 1;
  min-width: 0;
}
.studio .dock-text strong {
  color: var(--text);
  font-weight: 500;
}
.studio .dock-text small {
  color: var(--text-3);
  font-size: 11.5px;
}
.studio .dock-checks,
.studio .dock-time {
  color: var(--text-2);
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
}
.studio .dock-time {
  min-width: 48px;
  color: var(--accent);
  font-family: var(--mono);
  font-size: 12px;
  text-align: right;
}
.studio .dock-link strong {
  color: var(--text);
}
.studio .dock-cta {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  margin-left: auto;
  color: var(--text);
}
.studio .chat-input {
  border: 1px solid var(--line-strong);
  border-radius: 14px;
  background: var(--panel);
  box-shadow: 0 10px 30px -14px rgba(0, 0, 0, 0.7);
  transition: border-color 0.15s;
}
.studio .chat-input:focus-within {
  border-color: rgba(255, 255, 255, 0.24);
}
.studio .chat-input textarea {
  display: block;
  width: 100%;
  max-height: 180px;
  padding: 13px 16px 4px;
  border: 0;
  outline: 0;
  background: transparent;
  color: var(--text);
  font-size: 14px;
  line-height: 1.55;
  resize: none;
}
.studio .chat-input textarea::placeholder {
  color: var(--text-3);
}
.studio .chat-input.seeded textarea {
  opacity: 0.4;
}
.studio .chat-input-bar {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 6px 8px 8px 14px;
}
.studio .input-hint {
  flex: 1;
  color: var(--text-3);
  font-size: 11.5px;
  text-align: right;
}
.studio .send {
  display: grid;
  flex: none;
  place-items: center;
  width: 32px;
  height: 32px;
  border: 0;
  border-radius: 9px;
  background: var(--text);
  color: #0b0c0e;
  transition: background 0.12s, opacity 0.12s;
}
.studio .send .ico {
  stroke-width: 2;
}
.studio .send:hover:not(:disabled) {
  background: #fff;
}
.studio .send:disabled {
  opacity: 0.25;
}

.studio .toggle {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  color: var(--text-2);
  font-size: 12px;
  cursor: pointer;
  user-select: none;
}
.studio .toggle input {
  position: absolute;
  opacity: 0;
  pointer-events: none;
}
.studio .switch {
  position: relative;
  width: 26px;
  height: 15px;
  border-radius: 99px;
  background: rgba(255, 255, 255, 0.12);
  transition: background 0.15s;
}
.studio .switch::after {
  content: "";
  position: absolute;
  top: 2px;
  left: 2px;
  width: 11px;
  height: 11px;
  border-radius: 50%;
  background: var(--text);
  transition: transform 0.15s;
}
.studio .toggle input:checked + .switch {
  background: var(--accent);
}
.studio .toggle input:checked + .switch::after {
  transform: translateX(11px);
  background: #1b1503;
}
.studio .toggle input:focus-visible + .switch {
  outline: 2px solid rgba(245, 200, 76, 0.55);
  outline-offset: 2px;
}

/* Welcome */

.studio .welcome-wrap {
  display: grid;
  place-items: center;
}
.studio .welcome {
  display: grid;
  gap: 14px;
  width: 100%;
  max-width: 600px;
  padding: 32px 24px;
}
.studio .welcome-mark {
  display: grid;
  place-items: center;
  width: 40px;
  height: 40px;
  border-radius: 11px;
  background: var(--accent);
  color: #1b1503;
  font-size: 20px;
  font-weight: 700;
  box-shadow: 0 8px 30px -8px rgba(245, 200, 76, 0.5);
}
.studio .welcome h1 {
  margin-top: 6px;
  font-family: var(--display);
  font-size: 28px;
  font-weight: 600;
  letter-spacing: -0.035em;
  line-height: 1.15;
}
.studio .welcome > p {
  color: var(--text-2);
  font-size: 14px;
  line-height: 1.6;
}
.studio .suggestions {
  display: grid;
  gap: 8px;
  margin-top: 8px;
}
.studio .suggestions button {
  display: flex;
  align-items: flex-start;
  gap: 10px;
  padding: 11px 13px;
  border: 1px solid var(--line);
  border-radius: 10px;
  background: var(--panel);
  color: var(--text-2);
  font-size: 13px;
  line-height: 1.5;
  text-align: left;
  transition: border-color 0.12s, color 0.12s, background 0.12s;
}
.studio .suggestions button .ico {
  margin-top: 2px;
  color: var(--accent);
}
.studio .suggestions button:hover {
  border-color: var(--line-strong);
  background: var(--raised);
  color: var(--text);
}
.studio .welcome-lessons {
  margin-top: 10px;
  padding-top: 14px;
  border-top: 1px solid var(--line);
}
.studio .welcome-lessons .side-label {
  padding: 0 0 4px;
}
.studio .welcome-lessons p {
  color: var(--text-2);
  font-size: 12.5px;
}

/* Live testing panel */

.studio .test-panel {
  display: grid;
  grid-template-rows: minmax(0, 1.15fr) minmax(220px, 1fr);
  gap: 12px;
  min-width: 0;
  min-height: 0;
  padding: 12px;
  background: var(--bg);
}
.studio .lanes {
  display: grid;
  grid-template-columns: minmax(0, 1.35fr) minmax(0, 1fr);
  gap: 12px;
  min-height: 0;
}
.studio .lane-stack {
  display: grid;
  grid-template-rows: minmax(0, 1fr) minmax(0, 1fr);
  gap: 12px;
  min-height: 0;
}
.studio .lane {
  position: relative;
  display: flex;
  flex-direction: column;
  min-width: 0;
  min-height: 0;
  border: 1px solid var(--line);
  border-radius: 10px;
  background: var(--panel);
  overflow: hidden;
}
.studio .lane-head {
  display: flex;
  flex: none;
  align-items: center;
  gap: 8px;
  height: 36px;
  padding: 0 12px;
  border-bottom: 1px solid var(--line);
  font-size: 12px;
}
.studio .lane-head strong {
  font-size: 12.5px;
  font-weight: 600;
}
.studio .lane-mark {
  width: 8px;
  height: 8px;
  border-radius: 2px;
  background: var(--text-3);
}
.studio .lane-mark.server {
  background: var(--good);
}
.studio .lane-mark.neatlogs {
  background: var(--neatlogs);
}
.studio .lane-mark.entire {
  background: var(--entire);
}
.studio .lane-live {
  display: none;
  align-items: center;
  gap: 5px;
  padding: 0 6px;
  border-radius: 99px;
  background: var(--good-soft);
  color: var(--good-text);
  font-size: 10.5px;
  font-weight: 600;
  line-height: 17px;
}
.studio .lane-live.on {
  display: inline-flex;
}
.studio .lane-live::before {
  content: "";
  width: 5px;
  height: 5px;
  border-radius: 50%;
  background: currentColor;
  animation: blink 1.4s ease-in-out infinite;
}
.studio .lane-meta {
  margin-left: auto;
  color: var(--text-3);
  font-size: 11.5px;
  white-space: nowrap;
}
.studio .lane-meta b {
  font-weight: 500;
}
.studio .lane-meta b.warn {
  color: var(--warn);
}
.studio .lane-meta b.error {
  color: var(--bad-text);
}
.studio .lane-body {
  flex: 1;
  min-height: 0;
  padding: 8px;
  overflow-y: auto;
}
.studio .lane-body > * {
  animation: rise 0.3s ease-out both;
}
.studio .lane-empty {
  padding: 6px 4px;
  color: var(--text-3);
  font-size: 12px;
}

.studio .lane-body.log {
  padding: 6px 0;
  background: #0d0e11;
  font-family: var(--mono);
  font-size: 11.5px;
  line-height: 1.6;
}
.studio .log-line {
  display: grid;
  grid-template-columns: 60px minmax(0, 1fr);
  gap: 8px;
  padding: 1px 12px;
  border-left: 2px solid transparent;
  color: #b9bcc4;
}
.studio .log-line time {
  color: #4f535c;
}
.studio .log-text {
  min-width: 0;
  overflow-wrap: anywhere;
}
.studio .log-line.warn {
  border-left-color: var(--warn);
  background: rgba(240, 180, 41, 0.05);
  color: #f3cf7a;
}
.studio .log-line.error {
  border-left-color: var(--bad);
  background: rgba(229, 72, 77, 0.07);
  color: #ff9a9d;
}
.studio .log-line.mine {
  border-left-color: var(--accent);
  color: var(--text);
}
.studio .log-src,
.studio .log-plugin {
  margin-right: 6px;
  padding: 0 5px;
  border-radius: 4px;
  font-size: 10.5px;
  font-style: normal;
}
.studio .log-plugin {
  background: rgba(245, 200, 76, 0.12);
  color: var(--accent);
}
.studio .log-src {
  background: rgba(143, 199, 245, 0.12);
  color: #8fc7f5;
}
.studio .log-src.benana {
  background: rgba(245, 200, 76, 0.12);
  color: var(--accent);
}
.studio .log-src.chat {
  background: rgba(168, 220, 194, 0.12);
  color: #a8dcc2;
}
.studio .lane .jump {
  bottom: 10px;
}

.studio .trace-card,
.studio .cp-card {
  display: grid;
  gap: 5px;
  padding: 9px 10px;
  border: 1px solid var(--line);
  border-radius: 8px;
  background: var(--bg);
}
.studio .trace-card + .trace-card,
.studio .cp-card + .cp-card {
  margin-top: 6px;
}
.studio .trace-card.live {
  border-color: rgba(79, 184, 208, 0.35);
}
.studio .trace-card.matched {
  border-color: rgba(79, 184, 208, 0.2);
}
.studio .trace-row {
  display: flex;
  align-items: center;
  gap: 7px;
  font-size: 12.5px;
}
.studio .trace-row strong {
  font-weight: 600;
}
.studio .trace-row .lane-meta {
  margin-left: 0;
}
.studio .trace-state {
  margin-left: auto;
  color: var(--text-2);
  font-size: 11.5px;
  white-space: nowrap;
}
.studio .trace-card.live .trace-state {
  color: var(--neatlogs);
}
.studio .trace-sub {
  display: flex;
  gap: 10px;
  color: var(--text-3);
  font-size: 11px;
}
.studio .trace-sub code {
  font-family: var(--mono);
}
.studio .role-dot {
  flex: none;
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: var(--text-3);
}
.studio .role-dot.spec {
  background: #a8dcc2;
}
.studio .role-dot.builder {
  background: #c7b4fa;
}
.studio .role-dot.playtester {
  background: #8fc7f5;
}
.studio .role-dot.fixer {
  background: #f5b98f;
}
.studio .trace-progress {
  position: relative;
  height: 3px;
  border-radius: 99px;
  background: rgba(79, 184, 208, 0.12);
  overflow: hidden;
}
.studio .trace-progress::after {
  content: "";
  position: absolute;
  inset: 0;
  width: 35%;
  border-radius: 99px;
  background: var(--neatlogs);
  animation: sweep 1.6s ease-in-out infinite;
}
.studio .span-strip {
  display: flex;
  gap: 2px;
  height: 6px;
}
.studio .span-strip i {
  flex: 1;
  border-radius: 2px;
  background: rgba(79, 184, 208, 0.55);
}
.studio .span-strip i.err {
  background: var(--bad);
}
.studio .trace-error {
  color: var(--bad-text);
  font-size: 11.5px;
}

.studio .cp-card strong {
  font-size: 12.5px;
  font-weight: 500;
}
.studio .cp-card.read {
  border-style: dashed;
}
.studio .cp-link {
  display: flex;
  align-items: center;
  gap: 6px;
}
.studio .sha-chip,
.studio .cp-chip {
  padding: 1px 6px;
  border-radius: 5px;
  font-family: var(--mono);
  font-size: 11px;
}
.studio .sha-chip {
  background: var(--raised);
  color: var(--text);
}
.studio .cp-chip {
  background: rgba(167, 139, 250, 0.14);
  color: #c4b1fc;
}
.studio .cp-arrow {
  width: 14px;
  height: 1px;
  background: var(--line-strong);
}

.studio .lesson-list {
  display: grid;
  margin: 10px 0 0;
  padding: 0;
  list-style: none;
}
.studio .lesson-list li {
  padding: 10px 0;
  border-top: 1px solid var(--line);
}
.studio .lesson-list li p {
  color: var(--text);
  font-size: 12.5px;
}
.studio .lesson-list li small {
  color: var(--text-3);
  font-size: 11.5px;
}

@media (max-width: 1360px) {
  .studio .build-chat {
    grid-template-columns: minmax(380px, 1fr) minmax(0, 1fr);
  }
  .studio .lanes {
    grid-template-columns: minmax(0, 1fr);
    grid-template-rows: minmax(0, 1fr) minmax(0, 1fr);
  }
  .studio .lane-stack {
    grid-template-columns: minmax(0, 1fr) minmax(0, 1fr);
    grid-template-rows: minmax(0, 1fr);
  }
}

